bool push(Kind kind) noexcept {
    if (study_catalog::find(kind) == nullptr || full()) {
        return false;
    }
    slots_[(head_ + size_) % capacity] = kind;
    ++size_;
    return true;
}

std::optional<Kind> peek(std::size_t index = 0) const noexcept {
    if (index >= size_) {
        return std::nullopt;
    }
    return slots_[(head_ + index) % capacity];
}

// Removes the logical front and returns it by value. Leaves slots_ and all
// surviving entries physically in place; only head_ and size_ advance.
std::optional<Kind> pop() noexcept {
    if (empty()) {
        return std::nullopt;
    }
    const Kind kind = slots_[head_];
    head_ = (head_ + 1) % capacity;
    --size_;
    return kind;
}

// Own a value copy of the producer and prefill three upcoming kinds.
static std::optional<Round> create(const study_grid::Grid& board,
                                  study_next::ScriptedSource source,
                                  int interval = 30) noexcept {
    if(interval<=0)return std::nullopt;
    Round round(source);
    round.board_=board;
    round.gravity_.interval=interval;
    round.kind_=round.source_.next();
    const auto spawn=study_catalog::make_piece(round.kind_);
    if(!spawn)return std::nullopt;
    for(std::size_t i=0;i<study_next::Queue::capacity;++i)
        if(!round.next_.push(round.source_.next()))return std::nullopt;
    if(study_collision::classify(board,*spawn)==study_collision::Placement::clear)
        round.active_=spawn;
    // Initial collision still yields a finished round with a full preview.
    return round;
}

const auto next_kind=candidate.next_.peek();
if(!next_kind)return Step::invalid;
const auto spawn=study_catalog::make_piece(*next_kind);
if(!spawn)return Step::invalid;
// A spawn attempt consumes the selected kind, even if its placement
// is blocked. Refill before publishing the finished state as well.
if(!candidate.next_.pop() || !candidate.next_.push(candidate.source_.next()))
    return Step::invalid;
candidate.kind_=*next_kind;

inline std::optional<Mesh> make_mesh(const study_next::Queue& queue) noexcept {
    Mesh mesh;
    for(std::size_t slot=0;slot<queue.size();++slot){
        const auto kind=queue.peek(slot);
        const auto* definition=kind?study_catalog::find(*kind):nullptr;
        if(!definition)return std::nullopt;
        for(auto cell:definition->cells){
            const double x=244.0+cell.column*6.0;
            const double y=40.0+slot*60.0+cell.row*6.0;
            for(auto vertex:study_board::quad_vertices({x,y,x+5.0,y+5.0}))
                mesh.vertices[mesh.count++]=vertex;
        }
    }
    return mesh;
}
